#:package Microsoft.Extensions.Hosting@10.0.0
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

foreach (var behavior in new[] { BackgroundServiceExceptionBehavior.StopHost, BackgroundServiceExceptionBehavior.Ignore })
{
    var b = Host.CreateApplicationBuilder();
    b.Logging.ClearProviders();
    b.Services.Configure<HostOptions>(o => o.BackgroundServiceExceptionBehavior = behavior);
    b.Services.AddHostedService<Boom>();
    using var host = b.Build();
    await host.StartAsync();
    await Task.Delay(500);
    var life = host.Services.GetRequiredService<IHostApplicationLifetime>();
    Console.WriteLine($"{behavior}: stopping={life.ApplicationStopping.IsCancellationRequested}");
    await host.StopAsync();
}

class Boom : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        await Task.Yield();
        throw new InvalidOperationException("SMTP down");
    }
}

using System.Collections.Concurrent;

var done = new ConcurrentDictionary<string, bool>();
var claimed = new ConcurrentDictionary<string, bool>();
int a = 0, b = 0;

async Task Check(string k)
{
    if (done.ContainsKey(k)) return;
    await Task.Delay(100);
    done[k] = true;
    Interlocked.Increment(ref a);
}

async Task Claim(string k)
{
    if (!claimed.TryAdd(k, true)) return;
    await Task.Delay(100);
    Interlocked.Increment(ref b);
}

await Task.WhenAll(Check("K"), Check("K"));
await Task.WhenAll(Claim("K"), Claim("K"));
Console.WriteLine($"{a}\n{b}");

